class Store implements RetirementStore {
 values=new Map<string,unknown>();
 async get<T>(key:string){return structuredClone(this.values.get(key)) as T|undefined;}
 async transaction<T>(action:(store:{get<T>(key:string):Promise<T|undefined>;put(key:string,value:unknown):Promise<void>})=>Promise<T>){const next=new Map(structuredClone([...this.values]));const result=await action({get:async<T>(key:string)=>structuredClone(next.get(key)) as T|undefined,put:async(key,value)=>{next.set(key,structuredClone(value));}});this.values=next;return result;}
}
const owner={kind:"owner"} as const;
let scope:{installationId:string;generation:string},target:{installationId:string;generation:string},retirement:RetentionAuthorityCore,authority:RestoreAuthorityPort,service:CanonicalRestore;
beforeEach(async()=>{scope={installationId:crypto.randomUUID(),generation:"g1"};target={...scope,generation:"externally-new"};const store=new Store(),plan=await retirementBootstrapPlan(env.DB,scope);retirement=new RetentionAuthorityCore(store,scope.installationId,plan.seal);await retirement.begin(plan.manifest);await retirement.seal(plan.seal);const snapshots=new SnapshotAuthorityCore(store,scope.installationId,view=>retirement.status(view));authority={observe:()=>snapshots.observe(),recordSnapshot:input=>snapshots.recordSnapshot(input),snapshotReceipt:op=>snapshots.snapshotReceipt(op),restoreTicket:op=>snapshots.restoreTicket(op),reserveRestore:input=>snapshots.reserveRestore(input),lookup:(id,keys)=>retirement.lookup(id,keys),record:(id,keys)=>retirement.record(id,keys)};service=new CanonicalRestore(env.DB,scope,target.generation,owner,authority,sourceRetirementGuard(scope.installationId,retirement),{sourceEpoch:"epoch",sourceGeneration:"capture"},()=>100);});
afterEach(async()=>{await env.DB.prepare("UPDATE assistant_retention_installation_gate SET state='idle' WHERE installation_id=?").bind(scope.installationId).run();});
async function bundle(snapshotScope=scope,operationId="snapshot"){const producer=new SnapshotProducer(env.DB,snapshotScope,owner,authority,()=>100);let begin=await producer.execute({kind:"snapshot.begin",operationId});for(let i=0;begin.state==="preparing"&&i<20;i++)begin=await producer.execute({kind:"snapshot.advance",operationId});const packets:SnapshotPacket[]=[];let cursor:string|null=null,index=0;do{const result=await producer.execute({kind:"snapshot.page",operationId,index,cursor});if(!("packet" in result))throw Error("page");packets.push(result.packet);cursor=result.packet.page.nextCursor??null;index++;}while(cursor);let sealed=await producer.execute({kind:"snapshot.seal",operationId});for(let i=0;!("manifest" in sealed)&&i<20;i++)sealed=await producer.execute({kind:"snapshot.advance",operationId});if(!("manifest" in sealed))throw Error("seal");const verifier=new SnapshotVerifier(sealed.manifest),records=[];for(const packet of packets)records.push(...await verifier.accept(packet));await verifier.finish();return planCanonicalRestore(sealed.manifest,records);}
async function restore(plan:Awaited<ReturnType<typeof bundle>>,operationId="restore"){let state=await service.execute({kind:"restore.begin",operationId,manifest:plan.manifest}) as {state:string};for(let i=0;state.state==="preparing"&&i<30;i++)state=await service.execute({kind:"restore.advance",operationId}) as {state:string};expect(state.state).toBe("importing");for(const step of plan.steps){let result=await service.execute({kind:"restore.row",operationId,row:{record:step.record,proof:step.proof},...(step.source?{source:step.source}:{})}) as {state:string};for(let i=0;result.state==="pending"&&i<10;i++)result=await service.execute({kind:"restore.row",operationId,row:{record:step.record,proof:step.proof},...(step.source?{source:step.source}:{})}) as {state:string};}}
async function finish(operationId="restore"){let result=await service.execute({kind:"restore.finish",operationId}) as {state:string;reason?:string};for(let i=0;["finalizing","pending"].includes(result.state)&&!result.reason&&i<50;i++)result=await service.execute({kind:"restore.advance",operationId}) as typeof result;return result;}
test("real sealed artifact imports only canonical rows into an inactive new generation, preserving live all-generation money and releasing writers with execution held",async()=>{
 const source=await new SourceController(env.DB,scope,owner).create({originKey:"note",text:"Synthetic canonical",occurredAt:1});const budget=new InferenceBudget(env.DB,{...scope,period:"UTC-period"});await budget.configure(100);await budget.reserve("uncertain","a".repeat(64),8);await budget.uncertain("uncertain");const plan=await bundle();await restore(plan);expect(await finish()).toMatchObject({state:"inactive_complete",execution:"inactive",financial:"preserved_live_all_generations"});expect(await new SourceAccess(env.DB,target).read(owner,source.id)).toBeNull();expect(await service.execute({kind:"restore.release",operationId:"restore"})).toMatchObject({state:"released_paused",execution:"held"});expect((await new SourceAccess(env.DB,target).read(owner,source.id))?.text).toBe("Synthetic canonical");expect(await budget.status()).toMatchObject({cap:100,committed:8});await budget.settle("uncertain","a".repeat(64),3);expect((await budget.status()).committed).toBe(3);await expect(budget.reserve("new","b".repeat(64),1)).rejects.toThrow("restore_runtime_paused");expect(await env.DB.prepare("SELECT COUNT(*) n FROM assistant_jobs WHERE installation_id=? AND generation=?").bind(...Object.values(target)).first("n")).toBe(0);expect(await env.DB.prepare("SELECT COUNT(*) n FROM assistant_budget_accounts WHERE installation_id=? AND generation=?").bind(...Object.values(target)).first("n")).toBe(0);
});
test("pre-ticket authority failure and lost gate ACK reuse the exact gate token; another alias cannot steal it and pause recovers writers",async()=>{
 await new SourceController(env.DB,scope,owner).create({originKey:"note",text:"Synthetic",occurredAt:1});const plan=await bundle();let fail=true,tokens:string[]=[];const port={...authority,reserveRestore:async(input:Parameters<RestoreAuthorityPort["reserveRestore"]>[0])=>{tokens.push(input.quiescenceToken);if(fail){fail=false;throw Error("authority unavailable before ticket");}return authority.reserveRestore(input);}};service=new CanonicalRestore(env.DB,scope,target.generation,owner,port,sourceRetirementGuard(scope.installationId,retirement),{sourceEpoch:"epoch",sourceGeneration:"capture"});await expect(service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest})).rejects.toThrow("authority unavailable");expect(await service.execute({kind:"restore.status",operationId:"restore"})).toMatchObject({state:"preparing_gate"});await expect(service.execute({kind:"restore.begin",operationId:"other",manifest:plan.manifest})).rejects.toThrow("owned_by_other");await service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest});expect(tokens).toHaveLength(2);expect(tokens[1]).toBe(tokens[0]);expect(await service.execute({kind:"restore.pause",operationId:"restore"})).toMatchObject({state:"paused",runtime:"held"});expect(await new SourceAccess(env.DB,scope).read(owner,(await env.DB.prepare("SELECT id FROM assistant_sources WHERE installation_id=? AND generation=?").bind(scope.installationId,scope.generation).first<string>("id"))!)).not.toBeNull();await service.execute({kind:"restore.resume",operationId:"restore"});expect(await authority.restoreTicket("restore")).toMatchObject({quiescenceToken:tokens[0]});
});
test("snapshot membership rejects altered bytes or a copied proof before any canonical write",async()=>{
 await new SourceController(env.DB,scope,owner).create({originKey:"note",text:"Synthetic",occurredAt:1});const plan=await bundle();await service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest});const step=plan.steps.find(row=>row.record.table==="assistant_sources")!;const changed=structuredClone(step);changed.record.value.title="forged";changed.record.hash=await bridgeHash(changed.record.value);await expect(service.execute({kind:"restore.row",operationId:"restore",row:{record:changed.record,proof:changed.proof},source:changed.source})).rejects.toThrow();expect(await env.DB.prepare("SELECT COUNT(*) n FROM assistant_sources WHERE installation_id=? AND generation=?").bind(...Object.values(target)).first("n")).toBe(0);
});
test("mirror authority failure resumes after its durable page without orphaning the gate or repeating completed external records",async()=>{
 const ids=[];for(let index=0;index<10;index++)ids.push((await new SourceController(env.DB,scope,owner).create({originKey:"retired-"+index,text:"Synthetic retired",occurredAt:1})).id);
 const plan=await bundle();for(const id of ids)await new SourceController(env.DB,scope,owner).withdraw(id,1);
 let records=0,failAt=9;const port={...authority,record:async(id:string,keys:string[])=>{records++;if(records===failAt)throw Error("synthetic authority unavailable");return authority.record(id,keys);}};
 const make=()=>new CanonicalRestore(env.DB,scope,target.generation,owner,port,sourceRetirementGuard(scope.installationId,port),capture,()=>200);service=make();expect(await service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest})).toMatchObject({state:"preparing"});
 const before=await env.DB.prepare("SELECT token,progress_json FROM assistant_retention_restore_sessions WHERE installation_id=? AND generation=?").bind(target.installationId,target.generation).first<{token:string;progress_json:string}>();expect(JSON.parse(before!.progress_json).after).not.toBeNull();
 await expect(service.execute({kind:"restore.advance",operationId:"restore"})).rejects.toThrow("synthetic authority");failAt=-1;service=make();expect(await service.execute({kind:"restore.advance",operationId:"restore"})).toMatchObject({state:"importing"});expect(records).toBe(11);expect(await env.DB.prepare("SELECT token FROM assistant_retention_restore_sessions WHERE installation_id=? AND generation=?").bind(target.installationId,target.generation).first("token")).toBe(before!.token);
});
test("lost D1 gate acknowledgement reconciles its original token before allocating one external ticket",async()=>{
 await new SourceController(env.DB,scope,owner).create({originKey:"note",text:"Synthetic",occurredAt:1});const plan=await bundle();let lose=true,reservations=0;
 const prepare=env.DB.prepare.bind(env.DB),db={prepare:(sql:string)=>{const statement=prepare(sql);if(!sql.includes("INSERT INTO assistant_retention_installation_gate"))return statement;const wrap=(current:D1PreparedStatement):D1PreparedStatement=>new Proxy(current,{get(value,key){if(key==="bind")return(...args:unknown[])=>wrap(value.bind(...args));if(key==="run")return async()=>{const result=await value.run();if(lose){lose=false;throw Error("synthetic gate ACK lost");}return result;};const item=Reflect.get(value,key,value);return typeof item==="function"?item.bind(value):item;}});return wrap(statement);},batch:env.DB.batch.bind(env.DB)} as D1Database;
 const port={...authority,reserveRestore:async(input:Parameters<RestoreAuthorityPort["reserveRestore"]>[0])=>{reservations++;return authority.reserveRestore(input);}};
 service=new CanonicalRestore(db,scope,target.generation,owner,port,sourceRetirementGuard(scope.installationId,retirement),capture);expect(await service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest})).toMatchObject({state:"importing"});expect(lose).toBe(false);const ticket=await authority.restoreTicket("restore");await service.execute({kind:"restore.begin",operationId:"restore",manifest:plan.manifest});expect(reservations).toBe(1);expect(await authority.restoreTicket("restore")).toEqual(ticket);
});
