 const source=await new SourceController(env.DB,scope,owner).create({originKey:"note",text:"Synthetic canonical",occurredAt:1});await new OwnerControl(env.DB,scope,owner,()=>100).execute({kind:"mission.put",operationId:"old-mission",id:"mission",expectedRevision:0,objective:"Synthetic intent",source:{id:source.id,revision:1},state:"active",nextEvaluationAt:1});
 const oldBudget=new InferenceBudget(env.DB,{...scope,period:"old"});await oldBudget.configure(100);await oldBudget.reserve("old-uncertain","a".repeat(64),8);await oldBudget.uncertain("old-uncertain");const plan=await bundle();await restore(plan);expect(await finish()).toMatchObject({state:"inactive_complete"});await service.execute({kind:"restore.release",operationId:"restore"});const seal=(await env.DB.prepare("SELECT seal FROM assistant_retention_generation_seals WHERE installation_id=? AND generation=?").bind(target.installationId,target.generation).first<string>("seal"))!;
