 expect(await env.DB.prepare("SELECT COUNT(*) n FROM assistant_missions WHERE installation_id=? AND generation=?").bind(target.installationId,target.generation).first("n")).toBe(0);expect(await env.DB.prepare("SELECT COUNT(*) n FROM assistant_follow_ups WHERE installation_id=? AND generation=?").bind(target.installationId,target.generation).first("n")).toBe(0);
